insert into settings (id, data) values (1, '{"name":"Ndubuisi Jeremiah","brand":"Acegraphiix","role":"Brand Designer","sidebar_bio":"I''m Acegraphiix, a brand designer and strategist, focused on building bold and unforgettable visual systems and brand experiences.","hero_greeting":"Hi, I''m Acegraphiix,","hero_line_1":"Graphic designer","hero_line_2":"& Brand strategist","location":"Port Harcourt, Nigeria","available":true,"availability_label":"Available","announcement":"See my latest work","announcement_url":"/works","email":"acegraphiix@gmail.com","phone":"+234 903 207 5156","whatsapp":"2349032075156","handle":"@acegraphiix","socials":[{"label":"instagram","url":"https://instagram.com/acegraphiix"},{"label":"linkedin","url":""},{"label":"whatsapp","url":"https://wa.me/2349032075156"},{"label":"email","url":"mailto:acegraphiix@gmail.com"}],"avatar_url":"/img/avatar.jpg","cover_url":"/img/cover.jpg","portrait_url":"/img/portrait.jpg","projects_title":"Projects that\ntell you stories","projects_years":"23-26","services_title":"Crafting visuals\nthat lead, not follow.","services_intro":"I help brands shape strong visual identities and marketing designs through thoughtful strategy and design.","currency_note":"","process_title":"Crafting visuals","process_intro":"Every project begins with understanding the brand''s purpose, then evolves into a visual system that is distinctive, scalable, and built to create lasting impact.","stat_value":"98%","stat_label":"Client satisfaction rate","stat_text":"Trusted by founders and brands to deliver thoughtful creative direction, refined execution, and consistent design quality.","experience_title":"Building brands through design","philosophy_title":"Great design isn''t decoration.","philosophy_left":"I believe the strongest visual identities are built on a clear point of view. They create consistency, meaning, and recognition across every touchpoint.","philosophy_right":"As a brand designer and strategist, my role is to bring structure to ideas and emotion to strategy, translating business goals into visual experiences people genuinely remember.","philosophy_image_url":"/img/philosophy.jpg","testimonials_title":"What people\nsay about my work","clients_count":"","toolkit_text":"Over the years, I''ve built a flexible toolkit that allows me to move from concept to execution efficiently - balancing creativity with precision across different mediums.","archive_title":"From the archive","blog_title":"Space for journal","faq_intro":"Everything you need to know about my creative process, collaboration, and project expectations.","contact_title":"Let''s build\nsomething impactful.","contact_text":"If you''re looking to elevate your brand or create something meaningful, I''d love to collaborate.","about_body":"I''m Ndubuisi Jeremiah — known in the studio as Acegraphiix — a graphic designer and brand strategist based in Port Harcourt, Nigeria.\n\nI help businesses, creators and organisations look as good as the work they do: identities that hold together, social content that stops the scroll, and campaign visuals that bring people through the door.\n\nI''ve designed campaign and event visuals for the Lagos Internal Revenue Service, visual assets for Glidex Technologies, and brand identities, pitch decks and social designs for clients of Voise Agency in the UK.","drive_folder_url":"","seo_title":"Acegraphiix — Graphic Designer & Brand Strategist","seo_description":"Portfolio of Ndubuisi Jeremiah (Acegraphiix), a graphic designer and brand strategist in Port Harcourt, Nigeria, building bold visual systems and brand experiences."}'::jsonb) on conflict (id) do nothing;
