insert into faqs (question, answer, published, position) values ('Can you work with existing brands?', 'Yes, absolutely. I regularly work with established brands — whether that means expanding an existing visual system, creating new marketing collaterals, refreshing brand assets, or redesigning digital products while keeping the core identity intact. I adapt to existing guidelines and design systems to keep every touchpoint consistent.', true, 1);
insert into faqs (question, answer, published, position) values ('What types of projects do you take on?', 'I work on brand identities, creative direction, websites, digital products, marketing visuals, and design systems for startups, agencies, and growing businesses.', true, 2);
insert into faqs (question, answer, published, position) values ('How long does a typical project take?', 'Timelines vary with scope, deliverables and revision cycles.
insert into faqs (question, answer, published, position) values ('What do you need before we begin?', 'To kick off smoothly, I need:
